def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    c_opp = 0
    for i in range(n):
        if opp[i] == 'C':
            c_opp += 1
    d_opp = n - c_opp
    coop_rate = c_opp / n

    last_opp = opp[n - 1]

    # Immediate pure cases
    if d_opp == 0:
        # Exploit only very late, otherwise keep mutual cooperation
        if n >= 96:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    # Endgame: try to squeeze value from cooperative partners
    remaining = 100 - n
    if remaining <= 2:
        if coop_rate > 0.5 and last_opp == 'C':
            return 'D'
        if coop_rate > 0.8:
            return 'D'
        return 'C'

    # Tail defection streak
    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    # Tail cooperation streak
    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    # Discourage long exploitation with firm punishment
    if streak_d >= 3:
        return 'D'

    # If opponent is generally very cooperative:
    if coop_rate >= 0.85:
        # Punish a fresh defection briefly, otherwise preserve cooperation
        if streak_d == 1 and n >= 3 and opp[n - 2] == 'C':
            # Probably noise or isolated defection: forgive to restore CC
            return 'C'
        if streak_d == 2:
            # Short punishment, then expect return to cooperation
            return 'D'
        return 'C'

    # Detect TFT-like mirroring: if opponent copies our previous action heavily,
    # cooperate after our own defection to restore mutual cooperation quickly.
    if n >= 4:
        mirror = 0
        for i in range(1, n):
            if opp[i] == me[i - 1]:
                mirror += 1
        if mirror * 10 >= (n - 1) * 7:
            # Predict opponent mirrors last action; choose action to induce C next
            # If we cooperated last and they cooperated, cooperate.
            if me[n - 1] == 'C':
                return 'C'
            # If we defected and they defected, cooperate to break retaliation
            if me[n - 1] == 'D' and opp[n - 1] == 'D':
                return 'C'
            return 'C'

    # Pattern detection: alternating opponent
    if n >= 6:
        alt = 0
        for i in range(1, n):
            if opp[i] != opp[i - 1]:
                alt += 1
        if alt * 10 >= (n - 1) * 8:
            # Predict next to be opposite of last
            if last_opp == 'C':
                return 'D'
            return 'C'

    # Handle single defection in otherwise cooperative play: one punishment,
    # then forgive to allow return to mutual cooperation.
    if streak_d == 1:
        if coop_rate > 0.65:
            # Only punish if the defection feels deliberate (prior cooperation streak)
            if streak_c >= 2:
                return 'D'
            return 'C'
        if coop_rate > 0.5 and streak_c >= 3:
            return 'C'
        return 'D'

    if streak_d == 2:
        if coop_rate > 0.7:
            # Short punishment, then intend to cooperate if they resume C
            return 'D'
        return 'D'

    # Multi-defection recently: punish more, but keep room for recovery
    recent_start = n - 8 if n >= 8 else 0
    recent_d = 0
    for i in range(recent_start, n):
        if opp[i] == 'D':
            recent_d += 1
    if recent_d >= 4 and coop_rate < 0.6:
        return 'D'

    # Default: cooperate while opponent shows cooperative tendency,
    # but occasionally test very cooperative opponents early-mid game
    if last_opp == 'C':
        if coop_rate >= 0.7:
            return 'C'
        if coop_rate >= 0.4:
            return 'C'
        return 'D'

    # last_opp == 'D' with mild history: retaliate once then prepare to forgive
    if coop_rate > 0.6:
        return 'D'
    return 'D'
